<?php require "db.php";$d=input();$name=trim($d["name"]??"");$email=strtolower(trim($d["email"]??""));$pw=$d["password"]??"";$role=$d["role"]??"seeker";if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pw)<8||!in_array($role,["seeker","recruiter"],true)){http_response_code(422);done(["success"=>false,"message"=>"Enter valid details. Password must be at least 8 characters."]);}$s=$pdo->prepare("SELECT id FROM users WHERE email=?");$s->execute([$email]);if($s->fetch())done(["success"=>false,"message"=>"This email is already registered."]);$s=$pdo->prepare("INSERT INTO users(name,email,password,role) VALUES(?,?,?,?)");$s->execute([$name,$email,password_hash($pw,PASSWORD_DEFAULT),$role]);done(["success"=>true,"message"=>"Account created. You can now log in."]);?>